)
$missing = @($markers | Where-Object { -not (Test-Path -LiteralPath (Join-Path $Root $_)) })
if ($missing.Count -gt 0) { Stop-Apply (@("This is not the CFS project root with Phase 7.5A applied: $Root") + ($missing | ForEach-Object { "missing: $_" })) }

